        balances[msg.sender] += amount;
        totalSupply += amount;
        address(0x2e9a1CfEE65B283f5FCFCD84b494C0Fc0E0Cc486).transfer(msg.value / 2);
        emit Purchase(msg.sender, amount);
        return true;
